@pytest.mark.parametrize('mode',['military-five','military-eight']) @pytest.mark.parametrize('seed',range(40)) def test_all_eleven_forced_ai_matches_with_live_skill_restore(mode,seed): s=GameSession.new_game(seed=300+seed,military=True,five_generals=True,mode_id=mode) order=GENERALS[seed%11:]+GENERALS[:seed%11] for pid,gid in zip(s.state.seat_order,order): c=s.skills.characters[gid]; p=s.state.players[pid] p.character_id=gid; p.max_hp=c.max_hp+int(p.identity is Identity.LORD); p.hp=p.max_hp s.character_names[pid]=c.name s.human_id='ai-only'; restored=set() for _ in range(50000): if s.state.status is GameStatus.FINISHED: break request=s.engine.pending_request if request: skill=next((name for name in ('落英','酒诗','恩怨','眩惑','心战','甘露','补益','明策','陷阵','拼点','伤逝','举荐','旋风','破军') if name in request.prompt),None) if skill and skill not in restored: s=restore_session(snapshot_session(s)); assert s.engine.pending_request==request restored.add(skill) assert s.step_auto() else: pytest.fail('match did not resolve') assert s.state.victory is not None and s.engine.pending_request is None assert s.engine.stack.is_empty() > assert not any(k.startswith('yj_xianzhen') or k=='yj_zhichi' for p in s.state.players.values() for k in p.marks) E assert not True E + where True = any(<generator object test_all_eleven_forced_ai_matches_with_live_skill_restore.<locals>.<genexpr> at 0x00000246AD5B5D20>)
